-- Adapt existing Achieve-mint project to Laucobs Achievements catalog and stats.

-- Old unlocks reference Achieve-mint IDs that will be replaced.
truncate table public.character_achievements;

update public.characters
set total_points = 0,
    achievement_count = 0;

alter table public.achievements
  drop constraint if exists achievements_category_check;

delete from public.achievements;

alter table public.achievements
  add constraint achievements_category_check
  check (category in (
    'General',
    'Quests',
    'Combat',
    'Exploration',
    'Wealth',
    'Professions',
    'Dungeons',
    'Player vs Player',
    'Hardcore',
    'Feats of Strength'
  ));

alter table public.character_stats
  add column if not exists deaths integer not null default 0;

alter table public.character_stats
  drop column if exists quests_turned_in,
  drop column if exists lowest_hp_pct,
  drop column if exists survived_low_hp,
  drop column if exists naked_until_10;

-- Seed Laucobs Achievements catalog (190 achievements)
on conflict (id) do update set
  name = excluded.name,
  description = excluded.description,
  category = excluded.category,
  points = excluded.points,
  icon = excluded.icon;
